const listPublicGroups = `-- name: ListPublicGroups :many
SELECT g.id, g.name, g.slug, g.description, g.cover_key, g.owner_id, g.join_policy, g.member_count, g.created_at, g.deleted_at, u.name AS owner_name, gm.role AS my_role
FROM groups g
JOIN users u ON u.id = g.owner_id
LEFT JOIN group_members gm ON gm.group_id = g.id AND gm.user_id = $1
WHERE g.deleted_at IS NULL AND g.join_policy = 'public'
  AND ($2::timestamptz IS NULL OR (g.created_at, g.id) < ($2::timestamptz, $3::uuid))
ORDER BY g.created_at DESC, g.id DESC
LIMIT $4
`

